#!/usr/bin/env node
// MEL-UI-AUDIT (production, read-only): open MEL's real pages in a browser
// with the exact-SHA release-smoke identity, switch to every panel (a pure
// client-side tab change, never a mutation) and record what the owner would
// see broken: JavaScript errors, API calls failing on the server, and panels
// still stuck on a loading placeholder. API calls the read-only identity may
// not make answer 401/403: they are BLOCKED, never counted as failures.
// Usage: BASE_URL=… MEL_PARALLEL_PROOF=… node scripts/ui-production-audit.mjs > report.json

export const PAGES = ['/', '/professor'];
const PANELS = ['overview', 'chat', 'skills', 'roadmap', 'multi', 'memory', 'lora', 'connections', 'computer', 'diagnostics', 'terminal'];
const LOADING_RE = /^(chargement…?|chargement\.\.\.|lecture de l’état…|vérification…|état à charger…)$/i;
const SETTLE_MS = 6000;
// Requested by every panel; never evidence that a given panel loaded its data.
const SHARED_API = new Set(['/api/learning/progress']);

/** Pure classification, unit-tested: raw browser observations → report. */
export function summarizeUiAudit(observations = []) {
  const findings = [];
  let blocked = 0;
  let stuckBlocked = 0;
  let checked = 0;
  for (const page of observations) {
    for (const error of page.errors || []) findings.push({ code: 'UI_JS_ERROR', detail: `${page.path}${page.panel ? '#' + page.panel : ''} : ${String(error).slice(0, 200)}` });
    for (const call of page.responses || []) {
      checked++;
      if (call.status === 401 || call.status === 403) { blocked++; continue; }
      if (call.status >= 500) findings.push({ code: 'UI_API_SERVER_ERROR', detail: `${page.path} → ${call.method} ${call.path} HTTP ${call.status}` });
    }
    // Production proof 26/10: under the read-only identity most panels never
    // request their own data (only the shared progress call). A placeholder
    // there proves nothing about MEL: it is BLOCKED, not a finding.
    const ownCalls = new Set((page.responses || []).map(call => call.path).filter(path => !SHARED_API.has(path)));
    if (!ownCalls.size) { stuckBlocked += (page.stuck || []).length; continue; }
    for (const id of page.stuck || []) findings.push({ code: 'UI_STUCK_LOADING', detail: `${page.path}#${page.panel || '-'} : #${id} reste en chargement` });
  }
  // One finding per distinct problem, however many panels repeat it.
  const unique = [...new Map(findings.map(row => [row.code + row.detail.replace(/#[a-z-]+ :/, ':'), row])).values()];
  return { schema: 'mel.ui-production-audit/v1', pages: observations.length, api_calls: checked, blocked_calls: blocked, blocked_stuck: stuckBlocked, findings: unique.slice(0, 40) };
}

// MEL-UI-AUDIT-01: executable inventory of the visible controls. Each button
// is linked to the script that handles it (directly or through its form), the
// API paths that handler calls, and whether it would mutate (non-GET).
export function inventoryControls(html) {
  const source = String(html || '');
  const script = [...source.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(match => match[1]).join('\n');
  const escape = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const reference = id => new RegExp(`(#${escape(id)}\\b|getElementById\\(['"]${escape(id)}['"]\\))`);
  const controls = [];
  for (const match of source.matchAll(/<button\b([^>]*)>/g)) {
    const id = match[1].match(/\bid="([^"]+)"/)?.[1];
    if (!id) continue;
    let via = null, at = script.search(reference(id));
    if (at >= 0) via = 'script';
    else if (/\btype="submit"/.test(match[1])) {
      const form = source.slice(0, match.index).match(/<form\b[^>]*\bid="([^"]+)"[^>]*>(?![\s\S]*<\/form>)/)?.[1];
      if (form && (at = script.search(reference(form))) >= 0) via = 'form';
    }
    const handler = at >= 0 ? script.slice(at, at + 700) : '';
    controls.push({ id, handled: via !== null, via,
      api: [...new Set([...handler.matchAll(/['"](\/api\/[A-Za-z0-9/_.-]+)/g)].map(m => m[1]))].slice(0, 6),
      mutating: /method:\s*['"](?:POST|PUT|PATCH|DELETE)['"]/i.test(handler) });
  }
  return controls;
}

// Receipt per control: FAIL without a handler or with a JavaScript error,
// BLOCKED when its action would mutate (never clicked by a read-only audit),
// PASS otherwise. No unauthorized mutation is ever performed.
export function controlReceipt(controls = [], { jsErrors = [] } = {}) {
  const rows = controls.map(control => ({ id: control.id, api: control.api,
    status: !control.handled || jsErrors.length ? 'FAIL' : control.mutating ? 'BLOCKED' : 'PASS' }));
  const count = status => rows.filter(row => row.status === status).length;
  return { schema: 'mel.ui-control-receipt/v1', controls: rows, pass: count('PASS'), fail: count('FAIL'), blocked: count('BLOCKED'), mutations_performed: 0 };
}

// MEL-UI-AUDIT-02: browser recipe of the chat and media journeys. Each step
// (send, stream, interrupt, resume, attachment) must keep the requested mode
// and the references, and its render must say RESULT or ERROR — an error is
// never shown as a result.
export const CHAT_JOURNEY_STEPS = ['send', 'stream', 'interrupt', 'resume', 'attachment'];
export function chatJourneyReceipt(steps = []) {
  const rows = CHAT_JOURNEY_STEPS.map(step => {
    const seen = (Array.isArray(steps) ? steps : []).find(row => row?.step === step);
    if (!seen) return { step, status: 'BLOCKED', reason: 'NOT_OBSERVED' };
    const problems = [];
    if (seen.requested_mode && seen.mode !== seen.requested_mode) problems.push('MODE_LOST');
    const sent = (seen.sent_references || []).map(ref => ref?.url || ref);
    const kept = new Set((seen.references || []).map(ref => ref?.url || ref));
    if (sent.some(ref => !kept.has(ref))) problems.push('REFERENCE_LOST');
    if (!['RESULT', 'ERROR', 'PARTIAL_ERROR'].includes(seen.outcome)) problems.push('OUTCOME_UNMARKED');
    if (seen.failed === true && seen.outcome === 'RESULT') problems.push('ERROR_RENDERED_AS_RESULT');
    if (seen.archived_outcome && seen.archived_outcome !== seen.outcome) problems.push('ARCHIVE_OUTCOME_MISMATCH');
    return { step, status: problems.length ? 'FAIL' : 'PASS', problems };
  });
  const count = status => rows.filter(row => row.status === status).length;
  return { schema: 'mel.ui-chat-journey/v1', steps: rows, pass: count('PASS'), fail: count('FAIL'), blocked: count('BLOCKED') };
}

export async function observe(browser, baseUrl, headers, path, panel) {
  const context = await browser.newContext({ extraHTTPHeaders: headers });
  const page = await context.newPage();
  const errors = [];
  const responses = [];
  const aborted = [];
  // Requests this audit aborts (non-GET) reject as "Failed to fetch"; they
  // are the audit's own read-only guard, not a defect of the page.
  page.on('pageerror', error => { if (!/failed to fetch/i.test(error.message)) errors.push(error.message); });
  page.on('response', response => {
    const url = new URL(response.url());
    if (url.origin === new URL(baseUrl).origin && url.pathname.startsWith('/api/')) {
      responses.push({ method: response.request().method(), path: url.pathname, status: response.status() });
    }
  });
  // Read-only: block any non-GET request the page might start on its own.
  await page.route('**/*', route => {
    if (route.request().method() === 'GET') return route.continue();
    aborted.push(route.request().method() + ' ' + new URL(route.request().url()).pathname);
    return route.abort();
  });
  await page.goto(baseUrl + path, { waitUntil: 'domcontentloaded', timeout: 45_000 });
  if (panel) await page.evaluate(view => document.querySelector(`#nav button[data-view="${view}"]`)?.click(), panel);
  await page.waitForTimeout(SETTLE_MS);
  const stuck = await page.evaluate(source => {
    const re = new RegExp(source, 'i');
    const visible = el => el.offsetParent !== null;
    // Only the open panel: header elements depend on loaders this panel never ran.
    const scope = document.querySelector('section.view.active') || document;
    return [...scope.querySelectorAll('[id]')]
      .filter(el => el.children.length === 0 && visible(el) && re.test(el.textContent.trim()))
      .map(el => el.id).slice(0, 20);
  }, LOADING_RE.source);
  await context.close();
  return { path, panel, errors, responses, stuck, aborted };
}

async function main() {
  const baseUrl = String(process.env.BASE_URL || '').replace(/\/$/, '');
  const proof = String(process.env.MEL_PARALLEL_PROOF || '');
  if (!/^https:\/\//.test(baseUrl) || proof.length < 32) throw new Error('UI_AUDIT_CONFIG_MISSING');
  const { chromium } = await import('playwright-core').catch(() => import('playwright'));
  const browser = await chromium.launch(process.env.CHROME_PATH ? { executablePath: process.env.CHROME_PATH } : {});
  const headers = { 'x-mel-release-smoke': '1', 'x-mel-parallel-proof': proof };
  const observations = [];
  try {
    observations.push(await observe(browser, baseUrl, headers, '/', null));
    for (const panel of PANELS) observations.push(await observe(browser, baseUrl, headers, '/professor', panel));
  } finally {
    await browser.close();
  }
  if (process.env.UI_AUDIT_TRACE) console.error(JSON.stringify(observations.map(o => ({ panel: o.panel, responses: o.responses, aborted: o.aborted })), null, 1));
  process.stdout.write(JSON.stringify(summarizeUiAudit(observations), null, 2) + '\n');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch(error => { console.error(error.message); process.exit(1); });
}

export const CHAT_RICH_RENDERER_SOURCE = String.raw`
(function(){
  const BT=String.fromCharCode(96),FENCE=BT.repeat(3);
  const SAFE_PROTOCOLS=new Set(['http:','https:']);

  function safeUrl(raw){
    try{
      const value=String(raw||'').trim();if(!value)return null;
      const url=new URL(value,window.location.href);
      return SAFE_PROTOCOLS.has(url.protocol)&&!url.username&&!url.password?url.href:null;
    }catch{return null}
  }

  function safeMediaUrl(raw){
    const href=safeUrl(raw);if(!href)return null;
    const url=new URL(href),host=url.hostname.toLowerCase().replace(/^\[|\]$/g,'');
    if(url.origin===location.origin)return href;
    if(url.protocol!=='https:'||/^(?:localhost|127\.|0\.|10\.|192\.168\.|169\.254\.|172\.(?:1[6-9]|2[0-9]|3[01])\.|::|f[cd][0-9a-f]{2}:|fe[89ab][0-9a-f]:)/i.test(host)||/\.(?:localhost|local|internal)$/.test(host))return null;
    return href;
  }

  function mediaKind(href){
    let url;
    try{url=new URL(href)}catch{return ''}
    if(url.protocol!=='https:')return '';
    const path=url.pathname.toLowerCase();
    const host=url.hostname.toLowerCase();
    if(/\/api\/computer\/v1\/screenshot$/.test(path))return 'image';
    if(/\.(?:png|jpe?g|gif|webp|avif)$/.test(path))return 'image';
    if(/\.(?:mp3|wav|ogg|m4a|flac)$/.test(path))return 'audio';
    if(/\.(?:mp4|webm|ogv)$/.test(path))return 'video';
    if(host==='youtu.be'||host==='youtube.com'||host==='www.youtube.com'||host==='m.youtube.com')return 'youtube';
    if(host==='vimeo.com'||host==='www.vimeo.com'||host==='player.vimeo.com')return 'vimeo';
    return 'page';
  }

  function appendMedia(parent,href,alt,explicitKind){
    href=safeMediaUrl(href);if(!href)return false;
    const kind=explicitKind||mediaKind(href);
    if(!kind)return false;
    const box=document.createElement('figure');
    box.className='mel-rich-media';
    if(kind==='image'){
      const img=document.createElement('img');
      img.src=href;img.alt=String(alt||'');img.referrerPolicy='no-referrer';img.loading='lazy';
      box.appendChild(img);
    }else if(kind==='audio'){
      const audio=document.createElement('audio');
      audio.controls=true;audio.preload='none';audio.src=href;
      box.appendChild(audio);
    }else if(kind==='video'){
      const video=document.createElement('video');
      video.controls=true;video.preload='metadata';video.playsInline=true;video.src=href;
      box.appendChild(video);
    }else if(kind==='document'||kind==='page'){
      const a=document.createElement('a');a.href=href;a.textContent=String(alt||href);a.target='_blank';a.rel='noopener noreferrer';box.appendChild(a);
    }else{
      let src=href;
      if(kind==='youtube'){
        const url=new URL(href);
        const raw=url.hostname.toLowerCase()==='youtu.be'?url.pathname.split('/').filter(Boolean)[0]:(url.pathname.startsWith('/embed/')?url.pathname.split('/')[2]:url.searchParams.get('v'));
        const id=String(raw||'').replace(/[^A-Za-z0-9_-]/g,'').slice(0,20);
        if(!id)return false;
        src='https://www.youtube-nocookie.com/embed/'+id;
      }else if(kind==='vimeo'){
        const id=String(new URL(href).pathname.split('/').filter(Boolean).pop()||'').replace(/\D/g,'').slice(0,20);
        if(!id)return false;
        src='https://player.vimeo.com/video/'+id;
      }
      const frame=document.createElement('iframe');
      frame.src=src;frame.title=String(alt||new URL(href).hostname);frame.loading='lazy';frame.referrerPolicy='no-referrer';
      frame.setAttribute('sandbox','allow-scripts allow-popups allow-presentation');
      frame.setAttribute('allow','fullscreen; picture-in-picture');
      box.appendChild(frame);
      const caption=document.createElement('a');
      caption.href=href;caption.target='_blank';caption.rel='noopener noreferrer';caption.textContent=String(alt||href);
      box.appendChild(caption);
    }
    const playable=box.querySelector('img,audio,video');
    if(playable){playable.dataset.mediaStatus='pending';playable.addEventListener(playable.tagName==='IMG'?'load':'loadeddata',()=>{playable.dataset.mediaStatus='loaded'},{once:true});playable.addEventListener('error',()=>{playable.dataset.mediaStatus='unavailable';if(box.dataset.mediaError)return;box.dataset.mediaError='true';const link=document.createElement('a');link.href=href;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Média indisponible dans le lecteur — ouvrir la source';box.appendChild(link)},{once:true});}
    parent.appendChild(box);
    return true;
  }

  function appendText(node,value){node.appendChild(document.createTextNode(String(value??'')))}

  function appendInline(parent,value){
    const source=String(value??'');
    const token=/(!\[[^\]\n]*\]\((?:https?:\/\/)[^)\s]+\)|\[[^\]\n]+\]\((?:https?:\/\/)[^)\s]+\)|https?:\/\/[^\s<]+|\*\*[^*\n]+\*\*|__[^_\n]+__|\x60[^\x60\n]+\x60|~~[^~\n]+~~|\*[^*\n]+\*)/g;
    let cursor=0,match;
    while((match=token.exec(source))){
      if(match.index>cursor)appendText(parent,source.slice(cursor,match.index));
      const raw=match[0];
      if(raw.startsWith('![')){
        const parts=raw.match(/^!\[([^\]\n]*)\]\(([^)\s]+)\)$/);
        const href=parts?safeMediaUrl(parts[2]):null;
        if(href&&!/\.svg(?:$|\?)/i.test(href)){
          const img=document.createElement('img');
          img.className='mel-rich-inline';img.src=href;img.alt=parts[1]||'';img.referrerPolicy='no-referrer';
          parent.appendChild(img);
        }else appendText(parent,raw);
      }else if(raw.startsWith('[')){
        const parts=raw.match(/^\[([^\]\n]+)\]\(([^)\s]+)\)$/);
        const href=parts?safeUrl(parts[2]):null;
        if(href){
          const a=document.createElement('a');
          a.href=href;a.target='_blank';a.rel='noopener noreferrer';
          a.textContent=parts[1];parent.appendChild(a);
        }else appendText(parent,raw);
      }else if(/^https?:\/\//i.test(raw)){
        const cleaned=raw.replace(/[.,!?;:]+$/,'');
        const suffix=raw.slice(cleaned.length);
        const href=safeUrl(cleaned);
        if(href){
          const a=document.createElement('a');
          a.href=href;a.target='_blank';a.rel='noopener noreferrer';a.textContent=cleaned;
          parent.appendChild(a);
          if(suffix)appendText(parent,suffix);
        }else appendText(parent,raw);
      }else if((raw.startsWith('**')&&raw.endsWith('**'))||(raw.startsWith('__')&&raw.endsWith('__'))){
        const strong=document.createElement('strong');strong.textContent=raw.slice(2,-2);parent.appendChild(strong);
      }else if(raw.charCodeAt(0)===96&&raw.charCodeAt(raw.length-1)===96){
        const code=document.createElement('code');code.textContent=raw.slice(1,-1);parent.appendChild(code);
      }else if(raw.startsWith('~~')&&raw.endsWith('~~')){
        const del=document.createElement('del');del.textContent=raw.slice(2,-2);parent.appendChild(del);
      }else if(raw.startsWith('*')&&raw.endsWith('*')){
        const em=document.createElement('em');em.textContent=raw.slice(1,-1);parent.appendChild(em);
}else appendText(parent,raw);
      cursor=match.index+raw.length;
    }
    if(cursor<source.length)appendText(parent,source.slice(cursor));
  }

  function splitTableRow(line){
    let value=String(line||'').trim();
    if(value.startsWith('|'))value=value.slice(1);
    if(value.endsWith('|'))value=value.slice(0,-1);
    return value.split('|').map(cell=>cell.trim());
  }

  function isTableSeparator(line){
    const cells=splitTableRow(line);
    return cells.length>0&&cells.every(cell=>/^:?-{3,}:?$/.test(cell));
  }

  function isFence(line){
    const value=String(line||'').trimStart();
    return value.startsWith(FENCE)||value.startsWith('~~~');
  }

  function isBlockStart(lines,index){
    const line=String(lines[index]??'');
    if(!line.trim())return true;
    if(isFence(line))return true;
    if(/^\s{0,3}#{1,6}\s+/.test(line))return true;
    if(/^\s{0,3}>\s?/.test(line))return true;
    if(/^\s{0,3}[-*+]\s+/.test(line))return true;
    if(/^\s{0,3}\d+[.)]\s+/.test(line))return true;
    if(/^\s{0,3}(?:-{3,}|\*{3,}|_{3,})\s*$/.test(line))return true;
    return line.includes('|')&&index+1<lines.length&&isTableSeparator(lines[index+1]);
  }

  function renderRichText(target,value,metadata={}){
    if(typeof metadata==='string'){try{metadata=JSON.parse(metadata)}catch{metadata={}}}
    if(!metadata||typeof metadata!=='object')metadata={};
    if(!target||typeof target.replaceChildren!=='function')return false;
    const root=document.createElement('div');root.className='mel-rich';
    const lines=String(value??'').replace(/\r\n?/g,'\n').split('\n');
    let i=0;

    while(i<lines.length){
      const line=lines[i];
      if(!line.trim()){i++;continue}

      const standalone=String(line).trim();
      const imageLine=standalone.match(/^!\[([^\]\n]*)\]\((https?:\/\/[^)\s]+)\)$/);
      if(imageLine){
        const href=safeMediaUrl(imageLine[2]);
        if(href&&!/\.svg(?:$|\?)/i.test(href)){
          appendMedia(root,href,imageLine[1]||'','image');
          i++;continue;
        }
      }
      const lone=standalone.match(/^(https?:\/\/\S+)$/);
      if(lone){
        const href=safeUrl(lone[1].replace(/[.,!?;:]+$/,''));
        if(href&&appendMedia(root,href,'')){i++;continue}
      }

      if(isFence(line)){
        const trimmed=line.trimStart();
        const marker=trimmed.startsWith(FENCE)?FENCE:'~~~';
        const language=trimmed.slice(marker.length).trim().replace(/[^a-z0-9_+-]/gi,'').slice(0,40);
        const codeLines=[];i++;
        while(i<lines.length&&!String(lines[i]).trimStart().startsWith(marker)){codeLines.push(lines[i]);i++}
        if(i<lines.length)i++;
        const pre=document.createElement('pre'),code=document.createElement('code');
        if(language)code.className='language-'+language.toLowerCase();
        code.textContent=codeLines.join('\n');pre.appendChild(code);root.appendChild(pre);continue;
      }

      const heading=line.match(/^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/);
      if(heading){
        const h=document.createElement('h'+heading[1].length);appendInline(h,heading[2]);root.appendChild(h);i++;continue;
      }

      if(/^\s{0,3}(?:-{3,}|\*{3,}|_{3,})\s*$/.test(line)){
        root.appendChild(document.createElement('hr'));i++;continue;
      }

      if(/^\s{0,3}>\s?/.test(line)){
        const quote=document.createElement('blockquote'),parts=[];
        while(i<lines.length&&/^\s{0,3}>\s?/.test(lines[i])){
          parts.push(lines[i].replace(/^\s{0,3}>\s?/,''));i++;
        }
        parts.forEach((part,index)=>{if(index)quote.appendChild(document.createElement('br'));appendInline(quote,part)});
        root.appendChild(quote);continue;
      }

      if(/^\s{0,3}[-*+]\s+/.test(line)||/^\s{0,3}\d+[.)]\s+/.test(line)){
        const ordered=/^\s{0,3}\d+[.)]\s+/.test(line),list=document.createElement(ordered?'ol':'ul');
        const pattern=ordered?/^\s{0,3}\d+[.)]\s+/:/^\s{0,3}[-*+]\s+/;
        while(i<lines.length&&pattern.test(lines[i])){
          const li=document.createElement('li');appendInline(li,lines[i].replace(pattern,''));list.appendChild(li);i++;
        }
        root.appendChild(list);continue;
      }

      if(line.includes('|')&&i+1<lines.length&&isTableSeparator(lines[i+1])){
        const headers=splitTableRow(line),rows=[];i+=2;
        while(i<lines.length&&lines[i].includes('|')&&lines[i].trim()){rows.push(splitTableRow(lines[i]));i++}
        const wrap=document.createElement('div');wrap.className='mel-rich-table-wrap';
        const table=document.createElement('table'),thead=document.createElement('thead'),tr=document.createElement('tr');
        headers.forEach(cell=>{const th=document.createElement('th');appendInline(th,cell);tr.appendChild(th)});
        thead.appendChild(tr);table.appendChild(thead);
        const tbody=document.createElement('tbody');
        rows.forEach(row=>{const r=document.createElement('tr');headers.forEach((_,index)=>{const td=document.createElement('td');appendInline(td,row[index]??'');r.appendChild(td)});tbody.appendChild(r)});
        table.appendChild(tbody);wrap.appendChild(table);root.appendChild(wrap);continue;
      }

      const paragraph=[];
      while(i<lines.length&&lines[i].trim()&&!isBlockStart(lines,i)){paragraph.push(lines[i]);i++}
      if(!paragraph.length){paragraph.push(lines[i]);i++}
      const p=document.createElement('p');
      paragraph.forEach((part,index)=>{if(index)p.appendChild(document.createElement('br'));appendInline(p,part)});
      root.appendChild(p);
    }

    for(const item of Array.isArray(metadata?.media)?metadata.media.slice(0,12):[]){
      const href=safeMediaUrl(item?.url),kind=String(item?.type||'');
      if(!href||!['image','audio','video','document'].includes(kind))continue;
      const url=new URL(href);
      if(url.protocol!=='https:'&&url.origin!==location.origin)continue;
      if(/^(?:localhost|127\.|0\.|10\.|192\.168\.|169\.254\.|172\.(?:1[6-9]|2[0-9]|3[01])\.|\[::1\])/i.test(url.hostname)&&url.origin!==location.origin)continue;
      if(/\.svg(?:$|[?#])/i.test(href)||String(item.mime||'').split(';',1)[0].trim().toLowerCase()==='image/svg+xml')continue;
      const existing=[...root.querySelectorAll(kind==='document'?'a[href]':'[src]')].some(node=>(node.src||node.href)===href);
      if(!existing){
        appendMedia(root,href,item.title||kind,kind);
        if(item.attribution){const credit=document.createElement('p');credit.textContent=String(item.attribution).slice(0,300);root.appendChild(credit)}
      }
    }
    for(const reference of Array.isArray(metadata?.references)?metadata.references.slice(0,20):[]){
      const href=safeUrl(reference?.url);if(!href||[...root.querySelectorAll('a[href]')].some(link=>link.href===href))continue;
